void dei_rs_execute( void )
{
	if( !get_rs_valet() )
	{
		dei_rs_state = dei_rs_gwr ; 
		
		dei_rs_ecm_start();

			wake_enter_flagged(WAKE_DEI_RS);

		while( dei_rs_state )
			{
				(dei_rs_state)();
			}

			wake_leave_flagged(WAKE_DEI_RS);
	}
	else
	{
		notify_send( NOTIFY_ERROR, NOTIFY_PLD_ERROR_RS_VALET );
	}
}

